namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS" },
        new() { Id = 2, Name = "Mathematics", Code = "MATH" },
        new() { Id = 3, Name = "English", Code = "ENG" },
        new() { Id = 4, Name = "Physics", Code = "PHYS" },
        new() { Id = 5, Name = "History", Code = "HIST" },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, object-oriented design, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and has contributed to several open-source projects. He received his PhD from Stanford University.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, CourseCode = "CS 301", Title = "Database Systems", Description = "Principles of database design, SQL, normalization, transaction processing, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Carol Wang", InstructorBio = "Dr. Wang worked at Oracle for a decade before joining academia. Her research focuses on distributed database systems.", DepartmentId = 1, IsFeatured = false },
        new() { Id = 4, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. David Okafor", InstructorBio = "Dr. Okafor is an award-winning educator with a passion for making calculus accessible. He holds a PhD in Applied Mathematics from Princeton.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Novak", InstructorBio = "Dr. Novak's research focuses on computational linear algebra and its applications in machine learning.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 6, CourseCode = "ENG 101", Title = "Academic Writing", Description = "Develop skills in analytical reading, critical thinking, and expository writing. Emphasis on thesis-driven essays and research methods.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Frank Hughes", InstructorBio = "Prof. Hughes is a published author and has taught writing at the university level for over 20 years.", DepartmentId = 3, IsFeatured = false },
        new() { Id = 7, CourseCode = "ENG 205", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present. Explores themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Grace Kim", InstructorBio = "Dr. Kim specializes in 20th-century American fiction and has received multiple teaching excellence awards.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 8, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Henry Patel", InstructorBio = "Dr. Patel is an experimental physicist whose research involves quantum optics. He brings real-world research examples into the classroom.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 9, CourseCode = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Irene Santos", InstructorBio = "Dr. Santos has published over 50 papers in condensed matter physics and mentors undergraduate research students.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 10, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural exchanges, and transformative events from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. James O'Brien", InstructorBio = "Dr. O'Brien is a medieval historian who has conducted archaeological research across Europe and the Middle East.", DepartmentId = 5, IsFeatured = false },
        new() { Id = 11, CourseCode = "HIST 202", Title = "Modern World History", Description = "Examines political revolutions, industrialization, colonialism, world wars, and globalization from 1500 to the present.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. Karen Liu", InstructorBio = "Dr. Liu specializes in East Asian history and transnational historical movements. She is the author of three books on modern Chinese history.", DepartmentId = 5, IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public string GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name ?? "Unknown";
}

