@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;
    private Dictionary<string, string> _errors = new();

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? "GET"))
        {
            _errors = Validate(Model);
            if (_errors.Count == 0)
            {
                _submitted = true;
                _selectedCourseTitle = Catalog.GetCourse(Model.CourseId)?.Title ?? "Unknown";
            }
        }
    }

    [CascadingParameter] public HttpContext? HttpContextAccessor { get; set; }

    private static Dictionary<string, string> Validate(EnrollmentRequest model)
    {
        var errors = new Dictionary<string, string>();
        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(model);

        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(model, context, results, true))
        {
            foreach (var result in results)
            {
                foreach (var member in result.MemberNames)
                {
                    if (!errors.ContainsKey(member))
                    {
                        errors[member] = result.ErrorMessage ?? "Invalid";
                    }
                }
            }
        }

        return errors;
    }
}

