@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will be notified once it is processed.</p>
    </div>
    <a href="/courses">Browse more courses</a>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <form method="post" action="/enroll" class="col-md-6">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" />
            @if (_errors.ContainsKey(nameof(Model.StudentName)))
            {
                <div class="text-danger">@_errors[nameof(Model.StudentName)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" placeholder="e.g., ABC12345" />
            @if (_errors.ContainsKey(nameof(Model.StudentId)))
            {
                <div class="text-danger">@_errors[nameof(Model.StudentId)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select">
                <option value="0">-- Select a course --</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseCode - @course.Title</option>
                }
            </select>
            @if (_errors.ContainsKey(nameof(Model.CourseId)))
            {
                <div class="text-danger">@_errors[nameof(Model.CourseId)]</div>
            }
        </div>

        <button type="submit" class="btn btn-primary">Submit Request</button>
        <a href="/courses" class="btn btn-link">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest? Model { get; set; }
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;
    private Dictionary<string, string> _errors = new();

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();
        Model ??= new EnrollmentRequest();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        // SupplyParameterFromForm only populates Model on POST
        if (Model is not null && !string.IsNullOrEmpty(Model.StudentName))
        {
            _errors = Validate(Model);
            if (_errors.Count == 0)
            {
                _submitted = true;
                _selectedCourseTitle = Catalog.GetCourse(Model.CourseId)?.Title ?? "Unknown";
            }
        }
    }

    private static Dictionary<string, string> Validate(EnrollmentRequest model)
    {
        var errors = new Dictionary<string, string>();
        var results = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(model);

        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(model, context, results, true))
        {
            foreach (var result in results)
            {
                foreach (var member in result.MemberNames)
                {
                    if (!errors.ContainsKey(member))
                    {
                        errors[member] = result.ErrorMessage ?? "Invalid";
                    }
                }
            }
        }

        return errors;
    }
}

